// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(c));
        vm.assume(nonOwner != address(this));
        vm.assume(amount <= address(this).balance);

        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(address(0), amount) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
